+		return nil, ErrNotFound
+	}
+	if err != nil {
+		return nil, err
+	}
+	return &u, nil
+}
+
+const userColumns = `id, email, password_hash, created_at`
+
+func (s *SQLiteStore) GetUserByEmail(ctx context.Context, email string) (*User, error) {
