	prefix := ""
	if i := strings.IndexByte(pattern, ' '); i >= 0 {
		prefix = pattern[:i] + " "
		pattern = pattern[i+1:]
	}
	trailingSlash := strings.HasSuffix(pattern, "/")
	pattern = strings.Trim(pattern, "{}")
	base := strings.TrimSuffix(pattern, "/")
	candidates := []string{prefix + pattern, prefix + base, prefix + base + "/", prefix + "{/}"}
